 function recordEvidence(type){if(scenario==='none'||caseResolved)return;if(caseEvidence.has(type))return;caseEvidence.add(type);log('Evidencia investigada: '+apps[type][1]);}
 function recordAction(id,label){if(scenario==='none'||caseResolved)return;if(caseActions.some(a=>a.id===id))return;caseActions.push({id,label,step:incidentStep});log('Acción del operador: '+label);if(id==='quarantine'||id==='process'){stopTimeline();clearScene();clearEffects();setBanner('✓ INCIDENTE CONTENIDO · INVESTIGA Y CIERRA EL EXPEDIENTE');}else if(id==='isolate'){setBanner('◈ RED VIRTUAL AISLADA · INVESTIGACIÓN EN CURSO');}}
 function finishCase(method){if(scenario==='none'||caseResolved)return;const observed=Math.min(4,caseEvidence.size),actionIds=new Set(caseActions.map(x=>x.id));const fast=caseActions.some(x=>x.step<=2);let score=20+observed*10+(actionIds.has('isolate')?15:0)+(actionIds.has('process')||actionIds.has('quarantine')?20:0)+(method==='backup'?15:method==='restore'?5:0)+(fast?10:0);score=Math.max(0,Math.min(100,score));caseOutcome={scenario,score,method,decision:incidentDecision,evidence:[...caseEvidence],actions:[...caseActions],steps:incidentStep};lastCaseOutcome=caseOutcome;caseResolved=true;stopTimeline();clearEffects();log('Expediente cerrado: '+score+'/100');announce('Caso terminado · '+score+'/100 puntos');}
 function stopTimeline(){if(incidentTimer!==null){clearInterval(incidentTimer);incidentTimer=null;}incidentPaused=false;}
 function setBanner(message){root.querySelector('#mosIncidentBanner').textContent=message;}
 function renderTimeline(){const pane=root.querySelector('#mosTimeline');if(!pane)return;pane.replaceChildren();if(scenario==='none'){pane.append(make('div','mos-muted','Selecciona un escenario para iniciar una investigación.'));return;}
 const data=incidents[scenario];pane.append(make('h3','',data.name));pane.append(make('p','mos-timeline-state',incidentPaused?'⏸ Simulación pausada':incidentStep>=data.steps.length?'✓ Secuencia completa · investiga el sistema':'● Incidente en evolución'));
 const list=make('ol','mos-timeline-list');data.steps.forEach(([name,detail],i)=>{const item=make('li',i<incidentStep?'done':i===incidentStep?'next':'future');item.append(make('strong','',name));item.append(make('small','',detail));list.append(item);});pane.append(list);
 const actions=make('div','mos-actions');const pause=make('button','mos-action',incidentPaused?'▶ Reanudar':'⏸ Pausar');pause.disabled=incidentStep>=data.steps.length;pause.addEventListener('click',()=>{incidentPaused=!incidentPaused;renderTimeline();});const step=make('button','mos-action','Siguiente paso →');step.disabled=incidentStep>=data.steps.length;step.addEventListener('click',()=>advanceIncident());const replay=make('button','mos-action','↻ Ver escena');replay.addEventListener('click',()=>showScene(scenario,incidentStep));const inspect=make('button','mos-action','Investigar');inspect.addEventListener('click',()=>openApp('incident'));actions.append(pause,step,replay,inspect);pane.append(actions);
 }
 function renderIncident(body){if(scenario==='none'){body.append(make('p','','Todavía no hay un incidente seleccionado.'));return;}const data=incidents[scenario];body.append(make('h3','',data.name));body.append(make('p','','Secuencia segura de demostración. Usa Explorador, Procesos, Visor de eventos y Seguridad para analizar lo ocurrido.'));const list=make('ol','mos-case-list');incidentTrail.forEach(e=>list.append(make('li','',e)));body.append(list);const block=make('div','mos-report');block.append(make('h3','','Evidencias y decisiones'));block.append(make('p','',`Aplicaciones examinadas: ${caseEvidence.size}/6 · Acciones defensivas: ${caseActions.length}`));if(incidentDecision)block.append(make('p','mos-muted','Decisión inicial de correo: '+({opened:'Se abrió la recreación',inspected:'Se inspeccionó',ignored:'Se ignoró'}[incidentDecision]||incidentDecision)));for(const a of caseActions)block.append(make('p','mos-muted',`✓ ${a.label} · etapa ${a.step}`));if(caseOutcome){block.append(make('h3','',`RESULTADO ${caseOutcome.score}/100`));block.append(make('p','',caseOutcome.score>=80?'Investigación sólida y respuesta temprana.':caseOutcome.score>=50?'Incidente contenido. Faltaron algunas evidencias o medidas.':'Caso cerrado con evidencias insuficientes. Repite e investiga antes de recuperar.'));}else{block.append(make('p','mos-muted','Consejo: examina archivos, procesos, correo, red y sucesos. Aísla el equipo y aplica una medida defensiva. Puedes cerrar el caso cuando quieras.'));const finish=make('button','mos-action','✓ Cerrar expediente y evaluar');finish.addEventListener('click',()=>{finishCase('manual');refresh('incident');renderTimeline();});block.append(finish);}body.append(block);const b=make('button','mos-action','Abrir Centro de seguridad');b.addEventListener('click',()=>openApp('security'));body.append(b);}
 function advanceIncident(){if(scenario==='none'||caseResolved||quarantined||!infected)return;const data=incidents[scenario];if(incidentStep>=data.steps.length){stopTimeline();return;}const i=incidentStep++;const [title,detail]=data.steps[i];incidentTrail.push(title+' — '+detail);log(data.name+': '+title);announce(title+' · '+detail);
 if(scenario==='cascade'&&i===1){beep('error');desktop.classList.add('mos-cascade');showScene('cascade',i);setBanner('▧ CASCADE · DESPLAZAMIENTO VISUAL FICTICIO');}
 if(scenario==='iloveyou'&&i===2){systemDialog('Archivo modificado','Mail 404 detectó una modificación en recuerdos.txt. Inspecciona el Explorador.');files['C:/Users/Operator/Documents/recuerdos.txt']='[CAMBIADO EN SIMULACIÓN] Recurso alterado por el incidente ILOVEYOU.';setBanner('✉ CORREO · CAMBIO EN ARCHIVO FICTICIO');showScene('iloveyou',i);}
 if(scenario==='blaster'&&i===1){systemDialog('Error de servicio RPC','El sistema virtual ha detectado un fallo grave. Reinicio simulado cancelable desde Seguridad.','error');setBanner('⚠ REINICIO DEL SISTEMA VIRTUAL SOLICITADO · CANCELADO');desktop.classList.add('mos-alert');showScene('blaster',i);}
 if(scenario==='wannacry'&&i===1){locked=true;setBanner('🔒 DOCUMENTOS VIRTUALES BLOQUEADOS');}
 if(scenario==='wannacry'&&i===2){desktop.classList.add('mos-ransom');systemDialog('Documentos bloqueados','Algunos documentos del ordenador virtual no están disponibles. Abre Seguridad para restaurarlos.','error');showScene('wannacry',i);}
 if(incidentStep===data.steps.length)stopTimeline();renderTimeline();refresh();}
 function runIncident(id){if(state!=='work')return;if(!incidents[id])return;const retainedDecision=incidentDecision;const retainedBackup=backup;reset();backup=retainedBackup;incidentDecision=retainedDecision;beep('error');scenario=id;caseOpenedAt=Date.now();infected=true;const data=incidents[id];processes.push({pid:404,name:data.process,cpu:37,risk:true});setBanner('⚠ INVESTIGACIÓN EN CURSO · '+data.name.toUpperCase());log('Inicio de caso educativo: '+data.name);renderTimeline();advanceIncident();root.querySelector('#mosTimeline').hidden=false;root.querySelector('#mosTimelineToggle').setAttribute('aria-expanded','true');incidentTimer=setInterval(()=>{if(!incidentPaused&&!caseResolved)advanceIncident();},6500);openApp('incident');}
 root.querySelector('#mosPower').addEventListener('click',powerOn);root.querySelector('#mosContinue').addEventListener('click',goLogin);root.querySelector('#mosEnter').addEventListener('click',signIn);root.querySelector('#mosShutdown').addEventListener('click',shutdown);document.getElementById('mosReset').addEventListener('click',()=>{reset();desktop.classList.remove('mos-cascade','mos-alert','mos-ransom');root.querySelector('#mosIncidentBanner').textContent='LABORATORIO AISLADO · SIN MALWARE';refresh();});
 root.querySelector('#mosStart').addEventListener('click',()=>{startMenu.hidden=!startMenu.hidden;if(!startMenu.hidden)startMenu.style.zIndex=String(++top+1000);root.querySelector('#mosStart').setAttribute('aria-expanded',String(!startMenu.hidden));});root.querySelector('#mosTimelineToggle').addEventListener('click',()=>{const pane=root.querySelector('#mosTimeline');pane.hidden=!pane.hidden;root.querySelector('#mosTimelineToggle').setAttribute('aria-expanded',String(!pane.hidden));});desktop.addEventListener('pointerdown',e=>{if(!e.target.closest('#mosStartMenu,#mosStart')){startMenu.hidden=true;root.querySelector('#mosStart').setAttribute('aria-expanded','false');}});root.addEventListener('keydown',e=>{if(state==='work'&&e.ctrlKey&&e.altKey&&e.key.toLowerCase()==='t'){e.preventDefault();openApp('tasks');}if(e.key==='Escape'){startMenu.hidden=true;root.querySelector('#mosStart').setAttribute('aria-expanded','false');}});root.querySelectorAll('[data-mos-app]').forEach(b=>b.addEventListener('click',()=>openApp(b.dataset.mosApp)));document.querySelectorAll('[data-mos-incident]').forEach(b=>b.addEventListener('click',()=>runIncident(b.dataset.mosIncident)));root.querySelector('#mosClock').textContent=new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});setInterval(()=>{root.querySelector('#mosClock').textContent=new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});},30000);
 const immersiveButton=document.getElementById('mosImmersive');
 const immersiveExit=document.getElementById('mosExitImmersive');
 function setImmersive(enabled){document.body.classList.toggle('museum-immersive',enabled);immersiveButton.setAttribute('aria-pressed',String(enabled));immersiveButton.textContent=enabled?'▣ Volver a vista museo':'⛶ Entrar en modo inmersivo';immersiveExit.hidden=!enabled;if(enabled&&state==='off')powerOn();(enabled?immersiveExit:immersiveButton).focus();}
 immersiveButton.addEventListener('click',()=>setImmersive(!document.body.classList.contains('museum-immersive')));
 immersiveExit.addEventListener('click',()=>setImmersive(false));
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('museum-immersive')){if(root.querySelector('#mosStartMenu')?.hidden===false||root.querySelector('#mosLiveScene'))return;event.preventDefault();setImmersive(false);}});
 window.addEventListener('hashchange',()=>{if(location.hash!=='#museumos'&&document.body.classList.contains('museum-immersive'))setImmersive(false);});
 refresh();renderTimeline();view('off');root.querySelector('#mosOff').hidden=false;
